def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# can we clear camp group g with our current health and squad size?
def ok_goal(g, s):
    return group_threat(g) * group_hp(g) <= health() * strength() * s

# walk to camp goal g (dashing when far), attacking any camp in reach
def hunt(g):
    if distance(g, position()) == 0:
        if exists(nearest(camps)) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(nearest(camps)) ):
            move_towards( unit_position(nearest(camps)) )
            end_turn()
    if distance(position(), g) > 4:
        dash_to(0, g)
        dash_to(1, g)
    move_towards(g)
    if exists(first(filter(camps, in_attack_range()))):
        attack(first(filter(camps, in_attack_range())))
    set_priority( 1 + random_int(100) )
    end_turn()

